[tikz]
\begin{tikzpicture}[scale=1]
\draw[thick] (0,0) circle (1.7);
\fill (0,0) circle (1.5pt);
\draw (0,0)--(50:1.7) node[midway,above left,fill=white,inner sep=1pt] {$8\text{ cm}$};
\end{tikzpicture}
[/tikz]
Find the area of this circle in exact form, in terms of $\pi$.

[tikz]
\begin{tikzpicture}[scale=1]
\draw[thick] (0,0) circle (1.5);
\fill (0,0) circle (1.5pt);
\draw (0,0)--(50:1.5) node[midway,above left,fill=white,inner sep=1pt] {$4.5\text{ m}$};
\end{tikzpicture}
[/tikz]
Find the area of this circle, correct to $2$ decimal places.

[tikz]
\begin{tikzpicture}[scale=1]
\draw[thick] (0,0) circle (1.75);
\fill (0,0) circle (1.5pt);
\draw[{Stealth}-{Stealth}] (180:1.75)--(0:1.75) node[midway,below,fill=white,inner sep=1pt] {$14\text{ cm}$};
\end{tikzpicture}
[/tikz]
Find the area of this circle in exact form, in terms of $\pi$.

[tikz]
\begin{tikzpicture}[scale=1]
\draw[thick] (0,0) circle (1.4);
\fill (0,0) circle (1.5pt);
\draw[{Stealth}-{Stealth}] (180:1.4)--(0:1.4) node[midway,below,fill=white,inner sep=1pt] {$3.6\text{ m}$};
\end{tikzpicture}
[/tikz]
Find the area of this circle, correct to $1$ decimal place.

[tikz]
\begin{tikzpicture}[scale=1]
\begin{scope}[shift={(0,0)}]
\draw[thick] (0,0) circle (1.7);
\fill (0,0) circle (1.5pt);
\draw (0,0)--(50:1.7) node[midway,above left,fill=white,inner sep=1pt] {$6\text{ cm}$};
\node[below] at (0,-2.25) {Circle S};
\end{scope}
\begin{scope}[shift={(4.9,0)}]
\draw[thick] (0,0) circle (1.45);
\fill (0,0) circle (1.5pt);
\draw[{Stealth}-{Stealth}] (180:1.45)--(0:1.45) node[midway,below,fill=white,inner sep=1pt] {$10\text{ cm}$};
\node[below] at (0,-2) {Circle T};
\end{scope}
\end{tikzpicture}
[/tikz]
Find the difference between the areas of these two circles, correct to $2$ decimal places.
